use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store mapping variable names to integers.
/// A missing variable is taken to be -1.
pub fn eval(e: &Exp, store: &HashMap<String, i32>) -> i32 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(l, r) => eval(l, store) + eval(r, store),
        Exp::Mult(l, r) => eval(l, store) * eval(r, store),
    }
}

/// Perform a single‐step local peephole optimization at the root of the expression.
/// Does NOT recurse into subexpressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        // Multiplication rules:
        Exp::Mult(a, b) => {
            // take ownership of the child exps
            let left  = *a;
            let right = *b;
            match (left, right) {
                // absorbing element 0
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),
                // neutral element 1
                (Exp::Const(1), other) => other,
                (other, Exp::Const(1)) => other,
                // constant‐folding
                (Exp::Const(x), Exp::Const(y)) => Exp::Const(x * y),
                // nothing to do
                (l, r) => Exp::Mult(Box::new(l), Box::new(r)),
            }
        }

        // Addition rules:
        Exp::Plus(a, b) => {
            let left  = *a;
            let right = *b;
            match (left, right) {
                // neutral element 0
                (Exp::Const(0), other) | (other, Exp::Const(0)) => other,
                // constant‐folding
                (Exp::Const(x), Exp::Const(y)) => Exp::Const(x + y),
                // nothing to do
                (l, r) => Exp::Plus(Box::new(l), Box::new(r)),
            }
        }

        // Constants and variables are unchanged
        other => other,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_eval_and_optimize() {
        let mut store = HashMap::new();
        store.insert("x".into(), 5);
        store.insert("y".into(), 2);

        // (x * 1) + (0 * y)  ==> optimize root only: still Plus, but its left becomes x*1 -> x
        let expr = Exp::Plus(
            Box::new(Exp::Mult(Box::new(Exp::Var("x".into())), Box::new(Exp::Const(1)))),
            Box::new(Exp::Mult(Box::new(Exp::Const(0)), Box::new(Exp::Var("y".into())))),
        );

        assert_eq!(eval(&expr, &store), 5 + 0);

        let opt = optimize(expr);
        // root is still Plus, but left child is simplified to Var("x"), right to Const(0)
        if let Exp::Plus(l, r) = &opt {
            assert!(matches!(&**l, Exp::Var(v) if v == "x"));
            assert!(matches!(&**r, Exp::Const(0)));
        } else {
            panic!("expected a Plus at the root");
        }

        // And the value is preserved:
        assert_eq!(eval(&opt, &store), 5 + 0);
    }
}